it("test_XypicDiagramDrawer_triangle", () => {
  let A = new SymObject("A");
  let B = new SymObject("B");
  let C = new SymObject("C");
  let f = NamedMorphism(A, B, "f");
  let g = NamedMorphism(B, C, "g");
  let d = Diagram([f, g], new Map<Morphism, SetExpr | string>([[g.mul(f), "unique"]]));
  let grid = new DiagramGrid(d);
  let drawer = new XypicDiagramDrawer();
  expect(normalize(drawer.draw(d, grid)), "SymPy assertion 279 (line 518)").toEqual(normalize("\\xymatrix{\nA \\ar[d]_{g\\circ f} \\ar[r]^{f} & B \\ar[ld]^{g} \\\\\nC & \n}\n"));
  grid = new DiagramGrid(d, { transpose: true });
  drawer = new XypicDiagramDrawer();
  expect(normalize(drawer.draw(d, grid)), "SymPy assertion 280 (line 521)").toEqual(normalize("\\xymatrix{\nA \\ar[r]^{g\\circ f} \\ar[d]_{f} & C \\\\\nB \\ar[ru]_{g} & \n}\n"));
  expect(normalize(drawer.draw(d, grid, { masked: [g] })), "SymPy assertion 281 (line 522)").toEqual(normalize("\\xymatrix{\nA \\ar[r]^{g\\circ f} \\ar[d]_{f} & C \\\\\nB & \n}\n"));
  function formatter(astr: ArrowStringDescription): void {
  astr.label = "\\exists !" + astr.label;
  astr.arrowStyle = "{-->}";
}
  drawer.arrowFormatters.set("unique", formatter);
  expect(normalize(drawer.draw(d, grid)), "SymPy assertion 282 (line 528)").toEqual(normalize("\\xymatrix{\nA \\ar@{-->}[r]^{\\exists !g\\circ f} \\ar[d]_{f} & C \\\\\nB \\ar[ru]_{g} & \n}\n"));
  function defaultFormatter(astr: ArrowStringDescription): void {
  astr.labelDisplacement = "(0.45)";
}
  drawer.defaultArrowFormatter = defaultFormatter;
  expect(normalize(drawer.draw(d, grid)), "SymPy assertion 283 (line 533)").toEqual(normalize("\\xymatrix{\nA \\ar@{-->}[r]^(0.45){\\exists !g\\circ f} \\ar[d]_(0.45){f} & C \\\\\nB \\ar[ru]_(0.45){g} & \n}\n"));
  let f1 = NamedMorphism(B, A, "f1");
  let f2 = NamedMorphism(A, B, "f2");
  let g1 = NamedMorphism(C, B, "g1");
  let g2 = NamedMorphism(B, C, "g2");
  d = Diagram([f, f1, f2, g, g1, g2], new Map<Morphism, SetExpr | string>([[f1.mul(g1), "unique"], [g2.mul(f2), "unique"]]));
  grid = new DiagramGrid(d, { transpose: true });
  drawer = new XypicDiagramDrawer();
  expect(normalize(drawer.draw(d, grid, { masked: [f1.mul(g1).mul(g2).mul(f2), g2.mul(f2).mul(f1).mul(g1)] })), "SymPy assertion 284 (line 541)").toEqual(normalize("\\xymatrix{\nA \\ar[r]^{g_{2}\\circ f_{2}} \\ar[d]_{f} \\ar@/^3mm/[d]^{f_{2}} & C \\ar@/^3mm/[l]^{f_{1}\\circ g_{1}} \\ar@/^3mm/[ld]^{g_{1}} \\\\\nB \\ar@/^3mm/[u]^{f_{1}} \\ar[ru]_{g} \\ar@/^3mm/[ru]^{g_{2}} & \n}\n"));
});

