it("test_xypic_draw_diagram", () => {
  let A = new SymObject("A");
  let B = new SymObject("B");
  let C = new SymObject("C");
  let D = new SymObject("D");
  let E = new SymObject("E");
  let f = NamedMorphism(A, B, "f");
  let g = NamedMorphism(B, C, "g");
  let h = NamedMorphism(C, D, "h");
  let i = NamedMorphism(D, E, "i");
  let d = Diagram([f, g, h, i]);
  let grid = new DiagramGrid(d, { layout: "sequential" });
  let drawer = new XypicDiagramDrawer();
  expect(normalize(drawer.draw(d, grid)), "SymPy assertion 296 (line 633)").toEqual(normalize(xypicDrawDiagram(d, { layout: "sequential" })));
});
it('validates dimensions and represents empty diagrams without missing results', () => {
  expect(() => new GrowableGrid(-1, 2)).toThrow(RangeError);
  expect(() => new GrowableGrid(2, 1.5)).toThrow(RangeError);
  for (const options of [{}, { layout: 'sequential' as const }]) {
    const grid = new DiagramGrid(Diagram(), options);
    expect([grid.width, grid.height, grid.toString(), grid.toPretty()]).toEqual([0, 0, '[]', '']);
    expect(new XypicDiagramDrawer().draw(Diagram(), grid)).toBe('\\xymatrix{\n}\n');
  }
});
it('handles partial groups and multi-line symbolic object labels', () => {
  const A = new SymObject('A'), B = new SymObject('B'), C = new SymObject('C');
  const f = NamedMorphism(A, B, 'f'), g = NamedMorphism(B, C, 'g');
  const d = Diagram([f, g]);
  for (const groups of [[A, B, C], [finiteSet(A, B)], finiteSet(A, B, C), new Map([[finiteSet(A, B, C), {}]])]) {
    const grid = new DiagramGrid(d, { groups });
    expect(grid.toString()).toContain('Object("C")');
  }
  const grid = new DiagramGrid(d);
  expect(grid.toPretty()).toBe('A  B\n    \n   C');
  grid.grid.set(0, 0, new SymObject('long'));
  expect(grid.toPretty()).toContain('long');
  const symbolic = Diagram([NamedMorphism(finiteSet(A), B, 'u')]);
  const sg = new DiagramGrid(symbolic);
  expect(sg.toPretty()).toContain('A');
  expect(new XypicDiagramDrawer().draw(symbolic, sg)).toContain('\\left');
});
it('preserves all vertices and arrows across dense and sparse directed graphs', () => {
  let seed = 42;
  const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
  for (let sample = 0; sample < 30; sample++) {
    const objects = Array.from({ length: 4 + sample % 3 }, (_, i) => new SymObject('V' + i));
    const arrows: Morphism[] = [];
    for (let i = 0; i < objects.length; i++) for (let j = 0; j < objects.length; j++) if (i < j && arrows.length < 9 && random() < 0.15 + sample % 3 / 6) arrows.push(NamedMorphism(objects[i]!, objects[j]!, 'f' + i + 'x' + j));
    if (!arrows.length) continue;
    const d = Diagram(arrows), grid = new DiagramGrid(d);
    const cells = Array.from({ length: grid.height }, (_, i) => Array.from({ length: grid.width }, (_, j) => grid.get(i, j))).flat().filter((c) => c instanceof Expr);
    expect(cells.map((o) => o.key).sort()).toEqual(d.objects.args.map((o) => o.key).sort());
    const code = new XypicDiagramDrawer().draw(d, grid);
    expect(code.match(/\\ar/g)?.length ?? 0).toBe(grid.morphisms.size);
  }
});
it('routes crossing diagonals and short arrows around loops in every quadrant', () => {
  const A = new SymObject('A'), B = new SymObject('B'), C = new SymObject('C'), D = new SymObject('D');
  const vertices = [A, B, C, D];
  const arrows = vertices.flatMap((a, i) => vertices.map((b, j) => NamedMorphism(a, b, 'f' + i + j)));
  const d = Diagram([NamedMorphism(A, B, "ab"), NamedMorphism(B, C, "bc"), NamedMorphism(C, D, "cd")]), grid = new DiagramGrid(d);
  grid.morphisms.clear(); for (const m of arrows) grid.morphisms.set(m, finiteSet());
  const storage = new GrowableGrid<Expr>(3, 3);
  [[0, 0], [0, 2], [2, 0], [2, 2]].forEach(([i, j], k) => storage.set(i!, j!, vertices[k]!));
  Object.defineProperty(grid, 'grid', { value: storage });
  expect(new XypicDiagramDrawer().draw(d, grid).match(/\\ar/g)).toHaveLength(16);
});
it('weights labeled composites and respects custom loop and property formatters', () => {
  const A = new SymObject('A'), B = new SymObject('B'), C = new SymObject('C'), D = new SymObject('D');
  const f = NamedMorphism(A, B, 'f'), g = NamedMorphism(B, C, 'g'), h = NamedMorphism(C, D, 'h');
  const d = Diagram([f, g, h], new Map([[g.mul(f), 'composite']]));
  expect(new DiagramGrid(d).morphisms.has(g.mul(f))).toBe(true);
  const l = NamedMorphism(A, A, 'loop'), m = NamedMorphism(A, A, 'more');
  const loops = Diagram([l, m]); const grid = new DiagramGrid(loops);
  grid.morphisms.set(l, finiteSet(1));
  const drawer = new XypicDiagramDrawer(); drawer.defaultArrowFormatter = (a) => { a.loopingStart = 'custom'; a.loopingEnd = 'loop'; };
  expect(drawer.draw(loops, grid)).toContain('@(custom,loop)');
  const parallel = Diagram([f, NamedMorphism(A, B, 'f2'), g, h, NamedMorphism(A, D, 'long')]);
  expect(drawer.draw(parallel, new DiagramGrid(parallel, { layout: 'sequential' }))).toContain('long');
});
